  "test": "from types import SimpleNamespace
import pytest
from langfuse.span_filter import is_default_export_span

def _make_span(attributes=None):
    return SimpleNamespace(instrumentation_scope=None, attributes=attributes)

def test_default_export_includes_langfuse_custom_attribute():
    span = _make_span(attributes={"langfuse.custom": "value"})
    assert is_default_export_span(span) is True

def test_default_export_excludes_non_langfuse_attribute():
    span = _make_span(attributes={"other": "value"})
    assert is_default_export_span(span) is False"
